PROC
PROC_CRE_ProgressLanceAnimation((GUIDSTRING)_TimerHost)
AND
DB_CRE_Lance_AnimationIndex(_Index)
AND
IntegerSum(_Index, 1, _NewIndex)
AND
_NewIndex < 5
THEN
NOT DB_CRE_Lance_AnimationIndex(_Index);
DB_CRE_Lance_AnimationIndex(_NewIndex);
SetAnimationEventInt(S_CRE_LathanderLaser_3fcc818d-25e2-47c8-9e60-58c1c930a7db, "LathanderLaserPlayIndex",_NewIndex);
ObjectTimerLaunch(_TimerHost, "CRE_Lance_AnimationTimer", 6000, 0);

IF
DB_Destroyed(S_GLO_DevilishOx_AppleForm_2fb8359f-7fa7-4dab-8e0f-c1edef958a73)
AND
DB_Players((CHARACTER)_Player)
AND
GetPosition(S_GLO_DevilishOx_AppleForm_2fb8359f-7fa7-4dab-8e0f-c1edef958a73, _X, _Y, _Z)
AND
QRY_OnlyOnce("WYR_DevilishOx_AppleProvoked")
THEN
PROC_SetOnStage((CHARACTER)S_GLO_DevilishOx_49eb5b4b-c6ed-4d37-8f68-97b1128b7d56, 1);
AppearAtPosition(S_GLO_DevilishOx_49eb5b4b-c6ed-4d37-8f68-97b1128b7d56, _X, _Y, _Z, 1, NULL_00000000-0000-0000-0000-000000000000, "WYR_DevilishOx_AppleDestroyed");
PROC_MakeNPCHostile(S_GLO_DevilishOx_49eb5b4b-c6ed-4d37-8f68-97b1128b7d56, _Player);
PROC_WYR_MonsterRevealed_Reaction();

IF
TextEvent("LOW_OskarsBeloved_CreatePortrait")
AND
GetHostCharacter(_Player)
AND
CreateAtObject((ITEMROOT)FUR_GEN_Painting_Portrait_Square_Player_A_4069b438-2fd9-46c3-a5c0-a248039a3b52, S_LOW_OskarsBeloved_CounterfeitAsylumPos_eb28fccf-cbf9-461e-b9b3-3a74e6181aea, 0, 0, "LOW_OskarsBeloved_SpawnedPlayerPortrait", 1, _Portrait)
THEN
DB_OskarsBeloved_FuturePortraitName(_Player,"Test portrait");
AddCustomMaterialOverride(_Portrait, "6201596e-059a-4619-86d5-3c5db0957fc8");
SetCharacterOnPortraitPainting(_Player, _Portrait);
DB_OskarsBeloved_PlayerPortrait(_Player,_Portrait);
